        uint256 tokensForLiquidity = target.balanceOf(address(this)) / 100;

        // Add liquidity to the pool
        router.addLiquidityETH{value: ethForLiquidity}(
            address(target),
            tokensForLiquidity,
            0,
            0,
            address(this),
            block.timestamp
        );

        // Step 2: Impersonate owner to set operationsAddress
        vm.startPrank(target.owner());

        // Step 3: Set operationsAddress to attacker
        target.setOperationsAddress(address(this));

        // Step 4: Enable trading
